1	package com.loja.checkout.service;
2	
3	import com.loja.checkout.domain.Regiao;
4	import com.loja.checkout.domain.clube.NivelClube;
5	import com.loja.checkout.domain.cupom.ContextoCupom;
6	import com.loja.checkout.domain.cupom.Cupom;
7	import com.loja.checkout.domain.cupom.CupomFactory;
8	import com.loja.checkout.domain.entrega.ModalidadeEntrega;
9	import com.loja.checkout.domain.entrega.ModalidadeEntregaFactory;
10	import com.loja.checkout.domain.pagamento.AjustePagamento;
11	import com.loja.checkout.domain.pagamento.FormaPagamento;
12	import com.loja.checkout.domain.pagamento.FormaPagamentoFactory;
13	import com.loja.checkout.dto.ItemPedido;
14	import com.loja.checkout.dto.PedidoRequest;
15	import com.loja.checkout.dto.ResumoResponse;
16	import com.loja.checkout.exception.CheckoutException;
17	import com.loja.checkout.util.Arredondamento;
18	import org.springframework.stereotype.Service;
19	
20	import java.math.BigDecimal;
21	
22	@Service
23	public class ResumoService {
24	
25	    public ResumoResponse calcularResumo(PedidoRequest request) {
26	        validarPedido(request);
27	
28	        // 1. Soma dos produtos
29	        BigDecimal subtotalProdutos = calcularSubtotalProdutos(request.itens());
30	        BigDecimal pesoTotal = calcularPesoTotal(request.itens());
31	
32	        // 2. Validar nível do clube
33	        NivelClube nivelClube = validarNivelClube(request.nivelClube());
34	
35	        // 3. Validar região
36	        Regiao regiao = validarRegiao(request.regiao());
37	
38	        // 4. Validar modalidade de entrega
39	        ModalidadeEntrega modalidade = validarModalidadeEntrega(request.modalidadeEntrega());
40	
41	        // 5. Verificar se modalidade está disponível
42	        if (!modalidade.estaDisponivel(pesoTotal)) {
43	            throw new CheckoutException("MODALIDADE_INDISPONIVEL");
44	        }
45	
46	        // 6. Calcular frete (pode ser zerado pelo OURO)
47	        BigDecimal frete = nivelClube.isentarFrete()
48	            ? BigDecimal.ZERO.setScale(2)
49	            : modalidade.calcularFrete(pesoTotal);
50	        int prazo = modalidade.obterPrazo();
51	
52	        // 7. Validar e aplicar cupom
53	        BigDecimal descontoCupom = BigDecimal.ZERO.setScale(2);
54	        if (request.cupom() != null && !request.cupom().isBlank()) {
55	            Cupom cupom = validarCupom(request.cupom());
56	            ContextoCupom contexto = new ContextoCupom(subtotalProdutos, frete, request.itens());
57	
58	            if (!cupom.eAplicavel(contexto)) {
59	                throw new CheckoutException("CUPOM_NAO_APLICAVEL");
60	            }
61	
62	            descontoCupom = cupom.calcularDesconto(contexto);
63	        }
64	
65	        // 8. Calcular seguro (sempre sobre o subtotal de produtos)
66	        BigDecimal seguro = Arredondamento.arredondar(
67	            subtotalProdutos.multiply(regiao.getPercentualSeguro())
68	        );
69	
70	        // 9. Total do pedido = produtos - desconto + frete + seguro
71	        BigDecimal totalPedido = subtotalProdutos
72	            .subtract(descontoCupom)
73	            .add(frete)
74	            .add(seguro);
75	
76	        // 10. Validar forma de pagamento
77	        FormaPagamento formaPagamento = validarFormaPagamento(request.formaPagamento());
78	
79	        // 11. Validar parcelas
80	        int parcelas = request.parcelas() != null ? request.parcelas() : 1;
81	        if (!formaPagamento.validarParcelas(parcelas)) {
82	            throw new CheckoutException("PARCELAMENTO_INVALIDO");
83	        }
84	
85	        // 12. Verificar se forma de pagamento está disponível
86	        if (!formaPagamento.estaDisponivel(totalPedido)) {
87	            throw new CheckoutException("FORMA_PAGAMENTO_INDISPONIVEL");
88	        }
89	
90	        // 13. Ajuste da forma de pagamento
91	        AjustePagamento ajustePagamento = formaPagamento.calcularAjuste(totalPedido, parcelas);
92	
93	        // 14. Benefícios do clube
94	        BigDecimal credito = nivelClube.calcularCredito(subtotalProdutos);
95	        boolean brinde = nivelClube.concederBrinde(subtotalProdutos);
96	
97	        return new ResumoResponse(
98	            subtotalProdutos,
99	            descontoCupom,
100	            frete,
101	            prazo,
102	            seguro,
103	            ajustePagamento.ajuste(),
104	            ajustePagamento.totalFinal(),
105	            parcelas,
106	            ajustePagamento.valorParcela(),
107	            credito,
108	            brinde
109	        );
110	    }
111	
112	    private void validarPedido(PedidoRequest request) {
113	        if (request.itens() == null || request.itens().isEmpty()) {
114	            throw new CheckoutException("PEDIDO_INVALIDO");
115	        }
116	
117	        for (ItemPedido item : request.itens()) {
118	            if (item.precoUnitario() == null || item.precoUnitario().compareTo(BigDecimal.ZERO) <= 0 ||
119	                item.quantidade() == null || item.quantidade() <= 0 ||
120	                item.pesoKg() == null || item.pesoKg().compareTo(BigDecimal.ZERO) <= 0) {
121	                throw new CheckoutException("PEDIDO_INVALIDO");
122	            }
123	        }
124	    }
125	
126	    private BigDecimal calcularSubtotalProdutos(java.util.List<ItemPedido> itens) {
127	        BigDecimal subtotal = BigDecimal.ZERO;
128	        for (ItemPedido item : itens) {
129	            BigDecimal totalItem = item.precoUnitario()
130	                .multiply(BigDecimal.valueOf(item.quantidade()));
131	            subtotal = subtotal.add(totalItem);
132	        }
133	        return Arredondamento.arredondar(subtotal);
134	    }
135	
136	    private BigDecimal calcularPesoTotal(java.util.List<ItemPedido> itens) {
137	        BigDecimal pesoTotal = BigDecimal.ZERO;
138	        for (ItemPedido item : itens) {
139	            BigDecimal pesoItem = item.pesoKg()
140	                .multiply(BigDecimal.valueOf(item.quantidade()));
141	            pesoTotal = pesoTotal.add(pesoItem);
142	        }
143	        return pesoTotal;
144	    }
145	
146	    private NivelClube validarNivelClube(String nivel) {
147	        if (nivel == null || nivel.isBlank()) {
148	            throw new CheckoutException("NIVEL_CLUBE_INVALIDO");
149	        }
150	
151	        try {
152	            return NivelClube.valueOf(nivel);
153	        } catch (IllegalArgumentException e) {
154	            throw new CheckoutException("NIVEL_CLUBE_INVALIDO");
155	        }
156	    }
157	
158	    private Regiao validarRegiao(String regiao) {
159	        if (regiao == null || regiao.isBlank()) {
160	            throw new CheckoutException("REGIAO_INVALIDA");
161	        }
162	
163	        try {
164	            return Regiao.valueOf(regiao);
165	        } catch (IllegalArgumentException e) {
166	            throw new CheckoutException("REGIAO_INVALIDA");
167	        }
168	    }
169	
170	    private ModalidadeEntrega validarModalidadeEntrega(String modalidade) {
171	        if (modalidade == null || modalidade.isBlank()) {
172	            throw new CheckoutException("MODALIDADE_INVALIDA");
173	        }
174	
175	        if (!ModalidadeEntregaFactory.existe(modalidade)) {
176	            throw new CheckoutException("MODALIDADE_INVALIDA");
177	        }
178	
179	        return ModalidadeEntregaFactory.obter(modalidade);
180	    }
181	
182	    private Cupom validarCupom(String codigo) {
183	        if (!CupomFactory.existe(codigo)) {
184	            throw new CheckoutException("CUPOM_INVALIDO");
185	        }
186	
187	        return CupomFactory.obter(codigo);
188	    }
189	
190	    private FormaPagamento validarFormaPagamento(String forma) {
191	        if (forma == null || forma.isBlank()) {
192	            throw new CheckoutException("FORMA_PAGAMENTO_INVALIDA");
193	        }
194	
195	        if (!FormaPagamentoFactory.existe(forma)) {
196	            throw new CheckoutException("FORMA_PAGAMENTO_INVALIDA");
197	        }
198	
199	        return FormaPagamentoFactory.obter(forma);
200	    }
201	}
