1	package com.loja.checkout.domain.pagamento;
2	
3	import com.loja.checkout.util.Arredondamento;
4	import java.math.BigDecimal;
5	import java.math.MathContext;
6	
7	public class Cartao implements FormaPagamento {
8	
9	    private static final BigDecimal TAXA_JUROS = new BigDecimal("0.0199");
10	
11	    @Override
12	    public AjustePagamento calcularAjuste(BigDecimal total, int parcelas) {
13	        if (parcelas <= 3) {
14	            return calcularSemJuros(total, parcelas);
15	        } else {
16	            return calcularComJuros(total, parcelas);
17	        }
18	    }
19	
20	    private AjustePagamento calcularSemJuros(BigDecimal total, int parcelas) {
21	        BigDecimal valorParcela = Arredondamento.arredondar(
22	            total.divide(BigDecimal.valueOf(parcelas), MathContext.DECIMAL128)
23	        );
24	        BigDecimal totalFinal = total;
25	        BigDecimal ajuste = BigDecimal.ZERO.setScale(2);
26	
27	        return new AjustePagamento(ajuste, totalFinal, valorParcela);
28	    }
29	
30	    private AjustePagamento calcularComJuros(BigDecimal total, int parcelas) {
31	        // Fórmula Price: parcela = total × taxa ÷ (1 − (1 + taxa)^−n)
32	        BigDecimal umMaisTaxa = BigDecimal.ONE.add(TAXA_JUROS);
33	        BigDecimal fatorPotencia = umMaisTaxa.pow(-parcelas, MathContext.DECIMAL128);
34	        BigDecimal denominador = BigDecimal.ONE.subtract(fatorPotencia);
35	
36	        BigDecimal valorParcela = total.multiply(TAXA_JUROS)
37	            .divide(denominador, MathContext.DECIMAL128);
38	        valorParcela = Arredondamento.arredondar(valorParcela);
39	
40	        BigDecimal totalFinal = valorParcela.multiply(BigDecimal.valueOf(parcelas));
41	        BigDecimal ajuste = totalFinal.subtract(total);
42	
43	        return new AjustePagamento(ajuste, totalFinal, valorParcela);
44	    }
45	
46	    @Override
47	    public boolean validarParcelas(int parcelas) {
48	        return parcelas >= 1 && parcelas <= 12;
49	    }
50	
51	    @Override
52	    public boolean estaDisponivel(BigDecimal total) {
53	        return true;
54	    }
55	}
